"""Composite (interaction) events produced by voice event composition."""

from __future__ import annotations

from abc import ABC, abstractmethod
from typing import Any, ClassVar, Dict, List, Optional

from pydantic import BaseModel, ConfigDict, Field

from rasa.core.channels.channel import OutputChannel, UserMessage
from rasa.core.channels.constants import (
    USER_CONVERSATION_SESSION_END,
    USER_CONVERSATION_SESSION_START,
    USER_CONVERSATION_SILENCE_TIMEOUT,
)
from rasa.shared.core.constants import MERGED_TRANSCRIPTS_METADATA_KEY
from rasa.shared.core.events import Event, UserBargeIn, UserInputSuppressed
from rasa.shared.nlu.constants import (
    COMMANDS,
    ENTITIES,
    INTENT,
    INTENT_NAME_KEY,
    PREDICTED_CONFIDENCE_KEY,
)


class CompositeEvent(BaseModel, ABC):
    """Processor-ready interaction event produced by event composition.

    User-turn events may carry the process-local monotonic time at which their
    input completed. The processor consumes this latency anchor before creating
    a `UserMessage`; it is never serialized or persisted. Lifecycle events
    leave it unset.
    """

    model_config = ConfigDict(frozen=True)

    # Whether the event records something the user did (speech, keypresses,
    # barge-in) rather than a session lifecycle or timeout signal.
    is_user_input: ClassVar[bool] = False

    # Process-local time when this event triggered a user turn.
    turn_triggered_at_monotonic: Optional[float] = Field(
        default=None,
        exclude=True,
        repr=False,
        description=(
            "Process-local monotonic time when this event triggered a user turn. "
            "None when the trigger time is unknown."
        ),
    )

    def __eq__(self, other: object) -> bool:
        """Compare by transferable content only.

        Excluded fields (the latency anchor) are metadata: like serialization
        and repr, equality does not observe them.
        """
        if not isinstance(other, CompositeEvent):
            return NotImplemented
        return type(self) is type(other) and self.model_dump() == other.model_dump()

    def __hash__(self) -> int:
        """Hash consistently with content-based equality.

        A type-based hash is intentionally coarse: the metadata dicts in the
        content are unhashable, and these events are never keyed in bulk.
        """
        return hash(type(self))

    @abstractmethod
    def to_user_message(
        self,
        output_channel: OutputChannel,
        sender_id: str,
        input_channel: str,
    ) -> Optional[UserMessage]:
        """Build a `UserMessage` counterpart for this event, if there is one."""
        ...

    def to_tracker_event(self) -> Optional[Event]:
        """Return the tracker event recording a signal that is not a user turn."""
        return None


class UserTranscript(CompositeEvent):
    """A composed user transcript created from one or more final transcripts."""

    is_user_input: ClassVar[bool] = True

    text: str
    metadata: Optional[Dict[str, Any]] = None

    def to_user_message(
        self,
        output_channel: OutputChannel,
        sender_id: str,
        input_channel: str,
    ) -> UserMessage:
        """Build the `UserMessage` for this transcript."""
        return _text_event_to_user_message(
            self.text, self.metadata, output_channel, sender_id, input_channel
        )


class UserDTMFInput(CompositeEvent):
    """A composed DTMF input created from one or more raw keypresses."""

    is_user_input: ClassVar[bool] = True

    text: str
    metadata: Dict[str, Any] = Field(default_factory=lambda: {"source": "dtmf"})
    field_name: Optional[str] = None

    def to_user_message(
        self,
        output_channel: OutputChannel,
        sender_id: str,
        input_channel: str,
    ) -> UserMessage:
        """Build a message carrying the DTMF target for either engine.

        CALM consumes the ``SetSlotCommand`` while Mantle consumes the
        process-local ``dtmf_field_name``.
        """
        if self.field_name is None:
            return _text_event_to_user_message(
                self.text,
                self.metadata,
                output_channel,
                sender_id,
                input_channel,
            )

        from rasa.dialogue_understanding.commands.set_slot_command import SetSlotCommand
        from rasa.shared.core.constants import SetSlotExtractor

        command = SetSlotCommand(
            name=self.field_name,
            value=self.text,
            extractor=SetSlotExtractor.CUSTOM.value,
        )
        parse_data = {
            INTENT: {INTENT_NAME_KEY: None, PREDICTED_CONFIDENCE_KEY: 0.0},
            ENTITIES: [],
            COMMANDS: [command.as_dict()],
        }
        return UserMessage(
            text=self.text,
            output_channel=output_channel,
            sender_id=sender_id,
            input_channel=input_channel,
            metadata=self.metadata,
            parse_data=parse_data,
            dtmf_field_name=self.field_name,
        )


class SilenceTimeoutInteractionEvent(CompositeEvent):
    """Processor-ready interaction event for an elapsed silence timeout."""

    timeout: float
    metadata: Optional[Dict[str, Any]] = None
    text: str = Field(default=USER_CONVERSATION_SILENCE_TIMEOUT, init=False)

    def to_user_message(
        self,
        output_channel: OutputChannel,
        sender_id: str,
        input_channel: str,
    ) -> UserMessage:
        """Build the `UserMessage` for this silence-timeout signal."""
        return _text_event_to_user_message(
            self.text, self.metadata, output_channel, sender_id, input_channel
        )


class SessionStartedInteractionEvent(CompositeEvent):
    """Composite event for a voice session start."""

    text: ClassVar[str] = USER_CONVERSATION_SESSION_START

    metadata: Dict[str, Any]

    def to_user_message(
        self,
        output_channel: OutputChannel,
        sender_id: str,
        input_channel: str,
    ) -> UserMessage:
        """Build the `UserMessage` for this session-start signal."""
        return _text_event_to_user_message(
            self.text, self.metadata, output_channel, sender_id, input_channel
        )


class SessionEndedInteractionEvent(CompositeEvent):
    """Composite event for a voice session end."""

    text: ClassVar[str] = USER_CONVERSATION_SESSION_END

    metadata: Optional[Dict[str, Any]] = None

    def to_user_message(
        self,
        output_channel: OutputChannel,
        sender_id: str,
        input_channel: str,
    ) -> UserMessage:
        """Build the `UserMessage` for this session-end signal."""
        return _text_event_to_user_message(
            self.text, self.metadata, output_channel, sender_id, input_channel
        )


class BargeInInteractionEvent(CompositeEvent):
    """Composite event recording an accepted user barge-in.

    It has no `UserMessage` counterpart. Instead of routing a message, the processor
    records a `UserBargeIn` on the tracker in chronological queue order.
    """

    is_user_input: ClassVar[bool] = True

    metadata: Optional[Dict[str, Any]] = None

    def to_user_message(
        self,
        output_channel: OutputChannel,
        sender_id: str,
        input_channel: str,
    ) -> None:
        """Barge-in has no user message; the processor records `UserBargeIn`."""
        return None

    def to_tracker_event(self) -> UserBargeIn:
        """Return the `UserBargeIn` recording this barge-in."""
        return UserBargeIn(metadata=self.metadata)


class UserInputSuppressedInteractionEvent(CompositeEvent):
    """User input intentionally excluded from engine processing."""

    is_user_input: ClassVar[bool] = True

    text: str
    modality: str
    reason: str
    metadata: Optional[Dict[str, Any]] = None

    def to_user_message(
        self,
        output_channel: OutputChannel,
        sender_id: str,
        input_channel: str,
    ) -> None:
        """Suppressed input has no user message counterpart."""
        return None

    def to_tracker_event(self) -> UserInputSuppressed:
        """Return the `UserInputSuppressed` recording this input."""
        return UserInputSuppressed(
            text=self.text,
            modality=self.modality,
            reason=self.reason,
            metadata=self.metadata,
        )


def metadata_with_merged_transcripts(
    metadata: Optional[Dict[str, Any]], transcripts: List[str]
) -> Dict[str, Any]:
    """Return metadata annotated with the raw transcripts merged into one turn."""
    updated_metadata = dict(metadata or {})
    updated_metadata[MERGED_TRANSCRIPTS_METADATA_KEY] = list(transcripts)
    return updated_metadata


def _text_event_to_user_message(
    text: str,
    metadata: Optional[Dict[str, Any]],
    output_channel: OutputChannel,
    sender_id: str,
    input_channel: str,
) -> UserMessage:
    """Build a simple text `UserMessage` for a composite event."""
    return UserMessage(
        text=text,
        output_channel=output_channel,
        sender_id=sender_id,
        input_channel=input_channel,
        metadata=metadata,
    )
